def find_lexicographically_smallest_good_permutation(n):
    if n == 2:
        return [2, 1]
    else:
        permutation = list(range(1, n + 1))
        for i in range(n):
            if i % 2 == 0:
                permutation[i] = i // 2 + 1
            else:
                permutation[i] = n - i // 2
        return permutation

